        const __m128d _ws8_n = _mm_loadu_pd(&twp[60]);
        const __m128d _wc9_n = _mm_loadu_pd(&twp[64]);
        const __m128d _ws9_n = _mm_loadu_pd(&twp[68]);
        const __m128d _wc10_n = _mm_loadu_pd(&twp[72]);
