        const __m128d z14 = _mm_loadu_pd(&zin[2*((size_t)14*Ls + k)]);
        const __m128d z30 = _mm_fmadd_pd(_wc14_n, z14, _mm_mul_pd(_ws14_n, _mm_permute_pd(z14, 0x1)));
        const __m128d z35 = _mm_add_pd(z19, z30);
        _mm_storeu_pd(&S[12], z35);
        const __m128d z45 = _mm_sub_pd(z19, z30);
        const __m128d z46 = _mm_xor_pd(_mm_permute_pd(z45, 0x1), _M_RE_n);
        _mm_storeu_pd(&S[44], z46);
        const __m128d z66 = _mm_add_pd(z63, z35);
        const __m128d z4 = _mm_loadu_pd(&zin[2*((size_t)4*Ls + k)]);
